B.a3c=new A.a3(B.iN,["State Flower","Foxtail Orchid (Rhynchostylis retusa)"],t.w)
B.a3b=new A.a3(B.iN,["State Butterfly","Kaiser-e-Hind (Teinopalpus imperialis)"],t.w)
